/* -----------------------------------------------------------------------
 * screen_saver.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — Frog-Tongue Screen Saver
 *
 * screen_saver.h explains what it does and has the state table. This file
 * is in three parts:
 *   1. the face: every shape as named coordinates (in screen pixels of
 *      the 240 x 320 portrait panel), and a function that adds its
 *      rectangles;
 *   2. the animation: which shapes each 40 ms step of the 4 s cycle
 *      paints;
 *   3. the timer: when the saver opens and closes.
 *
 * The face, top to bottom:
 *
 *          eyes        y  72..119   white, with a black slit
 *          nostrils    y 146..149   two dark dots
 *     ~~~  smile       y 173..195   24 dark-green dashes on a curve  ~~~
 *          mouth       y 170..221   maroon, opens around the smile
 *          tongue      y 196..291   pink, slides out of the mouth line
 *
 * No HAL functions are called. This file compiles on any host.
 * ----------------------------------------------------------------------- */

#include "screen_saver.h"
#include <stddef.h>

/* -----------------------------------------------------------------------
 * 1. The face
 * ----------------------------------------------------------------------- */
#define BAND_H              2U      /* every round shape is a stack of bands this tall:
                                     * a 2-px band always has an even pixel count */

/* Eyes: a white rounded block (a narrow band, a wide middle, a narrow
 * band) with a black slit across its middle */
#define EYE_LEFT_CX         64U     /* x of each eye's centre */
#define EYE_RIGHT_CX        176U
#define EYE_TOP_Y           72U     /* the eyes are y 72..119 */
#define EYE_CAP_W           32U     /* the narrow top and bottom bands: 32 x 8 */
#define EYE_CAP_H           8U
#define EYE_MID_W           48U     /* the wide middle: 48 x 32 */
#define EYE_MID_H           32U
#define PUPIL_W             24U     /* the black slit: 24 x 12, centred in the middle part */
#define PUPIL_H             12U

/* Nostrils: two small dark dots above the mouth */
#define NOSTRIL_LEFT_X      106U
#define NOSTRIL_RIGHT_X     128U
#define NOSTRIL_Y           146U
#define NOSTRIL_W           6U
#define NOSTRIL_H           4U

/* The shut smile: 24 short dashes, 8 x 6 each, along a curve from x 24 to
 * x 215. Their top y: 173 at the corners, 190 in the middle (a parabola;
 * the lowest dashes end at y 195, just above the mouth line at y 196). */
#define SMILE_DASHES        24U
#define SMILE_X0            24U
#define SMILE_DASH_W        8U
#define SMILE_DASH_H        6U
static const uint8_t k_smile_top_y[SMILE_DASHES] = {
    173U, 176U, 178U, 181U, 183U, 185U, 186U, 187U, 188U, 189U, 190U, 190U,
    190U, 190U, 189U, 188U, 187U, 186U, 185U, 183U, 181U, 178U, 176U, 173U
};

/* The open mouth: an ellipse centred at (120, 196) with half-axes 72 and
 * 26, drawn as 26 bands of 2 px from y 170 to y 221. Each band's
 * half-width is 72 * sqrt(1 - (dy / 26)^2), dy being the distance of the
 * band's middle from y 196, worked out once and written down here. */
#define MOUTH_CX            120U    /* the centre x of the mouth and of the tongue */
#define MOUTH_TOP_Y         170U    /* 196 - 26 */
#define MOUTH_BANDS         26U
#define MOUTH_BOTTOM_Y      (MOUTH_TOP_Y + MOUTH_BANDS * BAND_H)   /* 222: the first row below the mouth */
static const uint8_t k_mouth_half_w[MOUTH_BANDS] = {
    20U, 34U, 42U, 49U, 54U, 59U, 62U, 65U, 68U, 69U, 71U, 72U, 72U,
    72U, 72U, 71U, 69U, 68U, 65U, 62U, 59U, 54U, 49U, 42U, 34U, 20U
};
/* Which ring each band belongs to: 0 = the middle 8 bands, 1 = the 10
 * around them, 2 = the 4 at the top and the 4 at the bottom. The mouth
 * opens ring 0, 1, 2 (the lips part from the middle) and shuts ring 2, 1,
 * 0, one ring per frame. */
#define MOUTH_RINGS         3U
static const uint8_t k_mouth_ring[MOUTH_BANDS] = {
    2U, 2U, 2U, 2U, 1U, 1U, 1U, 1U, 1U, 0U, 0U, 0U, 0U,
    0U, 0U, 0U, 0U, 1U, 1U, 1U, 1U, 1U, 2U, 2U, 2U, 2U
};

/* The tongue: 32 px wide (x 104..135), sliding down from the mouth line
 * 16 px per frame to 96 px. Its last 16 px are a rounded tip of 8 bands,
 * and a darker 2-px groove runs down its middle into the first half of
 * the tip. Every mouth band is at least 20 px wide each side of the
 * centre, more than the tongue's 16, so inside the mouth what is behind
 * the tongue is always maroon, and below the mouth it is skin. */
#define TONGUE_X            104U
#define TONGUE_W            32U
#define TONGUE_HALF_W       16U
#define TONGUE_TOP_Y        196U    /* it comes out at the mouth line */
#define TONGUE_STEP_H       16U     /* it grows or shrinks this much per frame */
#define TIP_BANDS           8U      /* 8 bands x 2 px = the last 16 px */
static const uint8_t k_tip_half_w[TIP_BANDS] = { 16U, 16U, 15U, 15U, 14U, 12U, 10U, 7U };
#define GROOVE_X            119U    /* x 119..120: the middle of the tongue */
#define GROOVE_W            2U
#define GROOVE_INTO_TIP_H   8U      /* the groove ends half way into the tip */

/* The SD BUSY tag (tony_ui.c paints it): the top-left corner, away from
 * every shape that moves */
#define TAG_X               4U
#define TAG_Y               4U
#define TAG_W               64U
#define TAG_H               12U

_Static_assert(MOUTH_RINGS == SS_MOUTH_OPENING_FRAMES && MOUTH_RINGS == SS_MOUTH_CLOSING_FRAMES,
               "one mouth ring per opening and closing frame");
_Static_assert(TIP_BANDS * BAND_H == TONGUE_STEP_H && SS_TONGUE_OUT_FRAMES == SS_TONGUE_IN_FRAMES,
               "the tip is one step long, and the tongue goes back as far as it came out");
_Static_assert(TONGUE_X + TONGUE_HALF_W == MOUTH_CX && TONGUE_W == 2U * TONGUE_HALF_W &&
               GROOVE_X + GROOVE_W / 2U == MOUTH_CX, "the tongue and its groove are centred on the mouth");
_Static_assert(TONGUE_TOP_Y + SS_TONGUE_OUT_FRAMES * TONGUE_STEP_H <= SS_PANEL_H,
               "the tongue stays on the panel");
_Static_assert(TAG_Y + TAG_H <= EYE_TOP_Y && ((TAG_W * TAG_H) % 2U) == 0U,
               "the tag sits above the face's shapes, with an even pixel count");

/* The rects of one frame are collected in a list: add() appends one. */
typedef struct {
    ss_rect_t *out;
    uint8_t    n;
} rect_list_t;

/* Append one rectangle (an empty one, w or h 0, is left out). */
static void add(rect_list_t *list, uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint16_t colour)
{
    if (w == 0U || h == 0U || list->n >= SS_MAX_RECTS) {
        return;
    }
    list->out[list->n].x      = (uint16_t)x;
    list->out[list->n].y      = (uint16_t)y;
    list->out[list->n].w      = (uint16_t)w;
    list->out[list->n].h      = (uint16_t)h;
    list->out[list->n].colour = colour;
    list->n++;
}

/* One eye: white rounded block, then the black slit over it. */
static void add_eye(rect_list_t *list, uint32_t cx)
{
    uint32_t mid_y = EYE_TOP_Y + EYE_CAP_H;
    add(list, cx - EYE_CAP_W / 2U, EYE_TOP_Y, EYE_CAP_W, EYE_CAP_H, SS_RGB_EYE);                 /* top band */
    add(list, cx - EYE_MID_W / 2U, mid_y, EYE_MID_W, EYE_MID_H, SS_RGB_EYE);                      /* middle */
    add(list, cx - EYE_CAP_W / 2U, mid_y + EYE_MID_H, EYE_CAP_W, EYE_CAP_H, SS_RGB_EYE);          /* bottom band */
    add(list, cx - PUPIL_W / 2U, mid_y + (EYE_MID_H - PUPIL_H) / 2U, PUPIL_W, PUPIL_H, SS_RGB_PUPIL);   /* slit */
}

/* The shut smile: the dashes along their curve. */
static void add_smile(rect_list_t *list)
{
    for (uint32_t i = 0U; i < SMILE_DASHES; i++) {
        add(list, SMILE_X0 + i * SMILE_DASH_W, k_smile_top_y[i], SMILE_DASH_W, SMILE_DASH_H, SS_RGB_LIP);
    }
}

/* The whole face, mouth shut: the opening frame (35 rects). */
static void add_face(rect_list_t *list)
{
    add(list, 0U, 0U, SS_PANEL_W, SS_PANEL_H, SS_RGB_SKIN);                     /* skin, the whole panel */
    add_eye(list, EYE_LEFT_CX);
    add_eye(list, EYE_RIGHT_CX);
    add(list, NOSTRIL_LEFT_X, NOSTRIL_Y, NOSTRIL_W, NOSTRIL_H, SS_RGB_LIP);      /* nostrils */
    add(list, NOSTRIL_RIGHT_X, NOSTRIL_Y, NOSTRIL_W, NOSTRIL_H, SS_RGB_LIP);
    add_smile(list);
}

/* One ring of the mouth's bands, in maroon (opening) or skin (shutting). */
static void add_mouth_ring(rect_list_t *list, uint32_t ring, uint16_t colour)
{
    for (uint32_t b = 0U; b < MOUTH_BANDS; b++) {
        if (k_mouth_ring[b] != ring) {
            continue;
        }
        uint32_t half_w = k_mouth_half_w[b];
        add(list, MOUTH_CX - half_w, MOUTH_TOP_Y + b * BAND_H, 2U * half_w, BAND_H, colour);
    }
}

/* What is behind the tongue at row y: the open mouth, or skin below it. */
static uint16_t behind_tongue(uint32_t y)
{
    return (y < MOUTH_BOTTOM_Y) ? SS_RGB_MOUTH : SS_RGB_SKIN;
}

/* The top row of the tongue's tip while the tongue is length_px long. */
static uint32_t tip_top_y(uint32_t length_px)
{
    return TONGUE_TOP_Y + length_px - TONGUE_STEP_H;
}

/* The rounded tip, pink, from row tip_y down. */
static void add_tip(rect_list_t *list, uint32_t tip_y)
{
    for (uint32_t j = 0U; j < TIP_BANDS; j++) {
        uint32_t half_w = k_tip_half_w[j];
        add(list, MOUTH_CX - half_w, tip_y + j * BAND_H, 2U * half_w, BAND_H, SS_RGB_TONGUE);
    }
}

/* Rows y .. y + h - 1 of the tongue's column back to what is behind them:
 * two rects when they cross the bottom edge of the mouth. */
static void add_behind_tongue(rect_list_t *list, uint32_t y, uint32_t h)
{
    uint32_t end_y = y + h;
    if (y < MOUTH_BOTTOM_Y && end_y > MOUTH_BOTTOM_Y) {
        add(list, TONGUE_X, y, TONGUE_W, MOUTH_BOTTOM_Y - y, SS_RGB_MOUTH);
        add(list, TONGUE_X, MOUTH_BOTTOM_Y, TONGUE_W, end_y - MOUTH_BOTTOM_Y, SS_RGB_SKIN);
        return;
    }
    add(list, TONGUE_X, y, TONGUE_W, h, behind_tongue(y));
}

/* -----------------------------------------------------------------------
 * 2. The animation: what each step paints
 * Each step paints only what differs from the picture before it, so the
 * face is never redrawn and nothing flickers.
 * ----------------------------------------------------------------------- */

/* Tongue out, step 0..5: the tongue grows from 16 * step to 16 * (step + 1)
 * px. The old tip becomes straight tongue (its corners filled in pink),
 * the new tip goes below it, and the groove runs down over both. */
static void add_tongue_out_step(rect_list_t *list, uint32_t step)
{
    uint32_t old_len    = step * TONGUE_STEP_H;
    uint32_t new_len    = old_len + TONGUE_STEP_H;
    uint32_t groove_top = tip_top_y(new_len);

    if (old_len > 0U) {
        /* the old tip becomes straight tongue: its corners filled in pink */
        add(list, TONGUE_X, tip_top_y(old_len), TONGUE_W, TONGUE_STEP_H, SS_RGB_TONGUE);
        groove_top = tip_top_y(old_len);
    }
    add_tip(list, tip_top_y(new_len));                  /* the new rounded tip, at the tongue's new end */
    /* the groove, from the top of the old tip (at step 0, of the new tip)
     * down to half way into the new tip */
    add(list, GROOVE_X, groove_top, GROOVE_W, tip_top_y(new_len) + GROOVE_INTO_TIP_H - groove_top, SS_RGB_GROOVE);
}

/* Tongue in, step 0..5: the tongue shrinks by 16 px from 96 - 16 * step.
 * The old tip's rows go back to the mouth or the skin; the straight end
 * just above them becomes the new rounded tip: its corners go back too,
 * and the groove ends half way into it again. */
static void add_tongue_in_step(rect_list_t *list, uint32_t step)
{
    uint32_t old_len = (SS_TONGUE_IN_FRAMES - step) * TONGUE_STEP_H;
    uint32_t new_len = old_len - TONGUE_STEP_H;

    add_behind_tongue(list, tip_top_y(old_len), TONGUE_STEP_H);     /* the old tip's rows: mouth or skin again */
    if (new_len == 0U) {
        return;                                 /* all the way back in */
    }
    uint32_t tip_y = tip_top_y(new_len);
    for (uint32_t j = 0U; j < TIP_BANDS; j++) {
        uint32_t corner_w = TONGUE_HALF_W - k_tip_half_w[j];
        uint32_t y = tip_y + j * BAND_H;
        add(list, TONGUE_X, y, corner_w, BAND_H, behind_tongue(y));                          /* left corner */
        add(list, TONGUE_X + TONGUE_W - corner_w, y, corner_w, BAND_H, behind_tongue(y));    /* right corner */
    }
    /* the groove's lower half in the new tip back to pink: it ends half way into the tip */
    add(list, GROOVE_X, tip_y + GROOVE_INTO_TIP_H, GROOVE_W, TONGUE_STEP_H - GROOVE_INTO_TIP_H, SS_RGB_TONGUE);
}

/* The rects of one step of the cycle. */
static void add_step(rect_list_t *list, ss_state_t state, uint32_t step)
{
    switch (state) {
        case SS_MOUTH_OPENING:
            add_mouth_ring(list, step, SS_RGB_MOUTH);                       /* rings 0, 1, 2 */
            break;
        case SS_TONGUE_OUT:
            add_tongue_out_step(list, step);
            break;
        case SS_TONGUE_IN:
            add_tongue_in_step(list, step);
            break;
        case SS_MOUTH_CLOSING:
            add_mouth_ring(list, MOUTH_RINGS - 1U - step, SS_RGB_SKIN);     /* rings 2, 1, 0 */
            if (step == SS_MOUTH_CLOSING_FRAMES - 1U) {
                add_smile(list);                                            /* shut: the smile again */
            }
            break;
        default:
            break;                              /* CLOSED, HOLD, REST: nothing changes */
    }
}

/* How many frames each part of the cycle lasts. */
static uint32_t frames_in(ss_state_t state)
{
    switch (state) {
        case SS_CLOSED:        return SS_CLOSED_FRAMES;
        case SS_MOUTH_OPENING: return SS_MOUTH_OPENING_FRAMES;
        case SS_TONGUE_OUT:    return SS_TONGUE_OUT_FRAMES;
        case SS_HOLD:          return SS_HOLD_FRAMES;
        case SS_TONGUE_IN:     return SS_TONGUE_IN_FRAMES;
        case SS_MOUTH_CLOSING: return SS_MOUTH_CLOSING_FRAMES;
        case SS_REST:          return SS_REST_FRAMES;
        default:               return 1U;
    }
}

/* The part that follows: the table in screen_saver.h. */
static ss_state_t next_state(ss_state_t state)
{
    switch (state) {
        case SS_CLOSED:        return SS_MOUTH_OPENING;
        case SS_MOUTH_OPENING: return SS_TONGUE_OUT;
        case SS_TONGUE_OUT:    return SS_HOLD;
        case SS_HOLD:          return SS_TONGUE_IN;
        case SS_TONGUE_IN:     return SS_MOUTH_CLOSING;
        case SS_MOUTH_CLOSING: return SS_REST;
        default:               return SS_CLOSED;   /* REST: the next cycle */
    }
}

/* One frame done: the next step of this part, or the next part. */
static void advance(screen_saver_t *ss)
{
    ss->step++;
    if (ss->step >= frames_in(ss->state)) {
        ss->step  = 0U;
        ss->state = next_state(ss->state);
    }
}

/* The next step is due SS_FRAME_MS after this one. A caller that fell
 * behind (a long redraw) gets the missed steps one per frame from now on,
 * never in a burst: each step keeps to the per-frame budget. */
static void schedule_next_frame(screen_saver_t *ss, uint32_t now_ms)
{
    ss->next_frame_ms += SS_FRAME_MS;
    if ((int32_t)(now_ms - ss->next_frame_ms) >= 0) {
        ss->next_frame_ms = now_ms + SS_FRAME_MS;
    }
}

uint8_t ss_frame(screen_saver_t *ss, uint32_t now_ms, ss_rect_t *out, uint8_t max)
{
    rect_list_t list = { out, 0U };

    if (ss == NULL || out == NULL || max < SS_MAX_RECTS || ss->state == SS_OFF) {
        return 0U;
    }
    if (ss->state == SS_OPENING) {
        add_face(&list);
        ss->state         = SS_CLOSED;
        ss->step          = 0U;
        ss->next_frame_ms = now_ms + SS_FRAME_MS;
        return list.n;
    }
    /* The unsigned difference read as signed: wrap-safe, like tony_ui.c's timers */
    if ((int32_t)(now_ms - ss->next_frame_ms) < 0) {
        return 0U;                              /* the next step is not due yet */
    }
    schedule_next_frame(ss, now_ms);
    add_step(&list, ss->state, ss->step);
    advance(ss);
    return list.n;
}

void ss_tag_rect(ss_rect_t *out)
{
    if (out == NULL) {
        return;
    }
    out->x      = TAG_X;
    out->y      = TAG_Y;
    out->w      = TAG_W;
    out->h      = TAG_H;
    out->colour = SS_RGB_TAG;
}

/* -----------------------------------------------------------------------
 * 3. The timer: when the saver opens and closes
 * ----------------------------------------------------------------------- */
void ss_init(screen_saver_t *ss, uint32_t now_ms)
{
    if (ss == NULL) {
        return;
    }
    ss->state         = SS_OFF;
    ss->step          = 0U;
    ss->last_input_ms = now_ms;
    ss->next_frame_ms = now_ms;
}

bool ss_input(screen_saver_t *ss, uint32_t now_ms)
{
    if (ss == NULL) {
        return false;
    }
    ss->last_input_ms = now_ms;
    if (ss->state == SS_OFF) {
        return false;
    }
    ss->state = SS_OFF;                         /* it was showing: this input only wakes */
    return true;
}

bool ss_update(screen_saver_t *ss, uint32_t now_ms, bool allowed)
{
    if (ss == NULL) {
        return false;
    }
    if (!allowed) {
        ss->state         = SS_OFF;
        ss->last_input_ms = now_ms;             /* the 30 s start again once it is allowed */
        return false;
    }
    if (ss->state != SS_OFF) {
        return false;
    }
    if ((uint32_t)(now_ms - ss->last_input_ms) < SS_IDLE_MS) {
        return false;                           /* wrap-safe: an unsigned difference */
    }
    ss->state = SS_OPENING;
    return true;
}

bool ss_showing(const screen_saver_t *ss)
{
    return (ss != NULL) && (ss->state != SS_OFF);
}

bool ss_opening(const screen_saver_t *ss)
{
    return (ss != NULL) && (ss->state == SS_OPENING);
}

bool ss_allowed(ui_screen_t screen, bool popup_open, bool recording, bool preparing)
{
    if (screen == UI_SCREEN_FAULT || screen == UI_SCREEN_DEBUG) {
        return false;
    }
    return !popup_open && !recording && !preparing;
}
